import React from 'react';

//estilos
import "../../components/cliente.css";
//imagenes

// header y footer
import Header from '../../components/Header_c.jsx'; 
import Footer from '../../components/Footer.jsx';
const Carrito = () => {
    // debemos hacer que eso productos esten enla bd.JSON
    const productosEnCarrito = [
        {
            id: 1,
            nombre: "Sábana Cama Sencilla Paw Patrol",
            descripcion: "Color: Azul | Tamaño: 100x190 cm",
            precio: "85.000",
            cantidad: 1,
            imagen: "../imagenes/producto_1.png"
        },
        {
            id: 2,
            nombre: "Funda Decorativa Floral",
            descripcion: "Color: Rosa pastel | Material: Algodón",
            precio: "45.000",
            cantidad: 2,
            imagen: "/imagenes/producto_2.jpeg"
        }
    ];

    const resumenCompra = {
        subtotal: "175.000",
        envio: "10.000",
        total: "185.000"
    };

    return (
        <div className="app-container">
            <Header />

            <main className="contenido">
                <h1>Carrito de compras</h1>
                    <section className="buscador">
            <input type="text" placeholder="Buscar productos..." />
            <button>🔎</button>
            </section>
                <section className="lista-productos">
                    {productosEnCarrito.map(producto => (
                        <div className="producto" key={producto.id}>
                            <img src={producto.imagen} alt={producto.nombre} className="imagen" />
                            <div className="detalle">
                                <h2>{producto.nombre}</h2>
                                <p>{producto.descripcion}</p>
                                {/* Nota: Se cambió la clase de "precio" a "span" para mantener la estructura original, 
                                    y la clase CSS 'precio' se aplica directamente al span */}
                                <span className="precio">${producto.precio}</span>

                                <div className="acciones">
                                    <input type="number" defaultValue={producto.cantidad} min="1" />
                                    <button className="eliminar">Eliminar</button>
                                </div>
                            </div>
                        </div>
                    ))}
                </section>

                <section className="resumen">
                    <h3>Resumen de compra</h3>
                    <p>Subtotal: <span>${resumenCompra.subtotal}</span></p>
                    <p>Envío: <span>${resumenCompra.envio}</span></p>
                    <hr />
                    <p className="total">Total: <span>${resumenCompra.total}</span></p>
                    <a href="pago.html">
                        <button className="finalizar">Finalizar compra</button>
                    </a>
                </section>
            </main>

            <Footer />
        </div>
    );
};

export default Carrito;
